<?php
declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$rows=[];$tot=['debit'=>0.0,'credit'=>0.0];$from=trim((string)($_GET['from']??date('Y-m-01')));$to=trim((string)($_GET['to']??date('Y-m-t')));$q=trim((string)($_GET['q']??''));
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$from=finance_step16_date($from,'from date');$to=finance_step16_date($to,'to date');$sql="SELECT j.id journal_id,j.journal_number,j.journal_date,j.journal_type,j.memo,j.source_code,j.source_type,j.source_id,j.status,j.reversal_of_id,l.line_no,l.debit_amount,l.credit_amount,l.line_memo,a.account_code,a.account_name,a.account_class,c.account_name cash_account_name FROM finance_journals j JOIN finance_journal_lines l ON l.journal_id=j.id AND l.organization_id=j.organization_id JOIN finance_ledger_accounts a ON a.id=l.ledger_account_id AND a.organization_id=j.organization_id LEFT JOIN finance_cash_accounts c ON c.id=l.cash_account_id AND c.organization_id=j.organization_id WHERE j.organization_id=? AND j.journal_date BETWEEN ? AND ?";$args=[$orgId,$from,$to];if($q!==''){$sql.=" AND (j.journal_number LIKE ? OR j.memo LIKE ? OR a.account_name LIKE ? OR j.source_type LIKE ?)";$like='%'.$q.'%';array_push($args,$like,$like,$like,$like);}$sql.=" ORDER BY j.journal_date DESC,j.id DESC,l.line_no";$stmt=$pdo->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll();foreach($rows as $r){$tot['debit']+=(float)$r['debit_amount'];$tot['credit']+=(float)$r['credit_amount'];}}catch(Throwable $e){$error=$e->getMessage();}
function fj_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function fj_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Journal Ledger - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Journal Ledger</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_cashbook.php">Cashbook</a><a class="os-btn" href="finance_export.php">Export</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Finance</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a href="finance_entry.php"><i class="dot"></i>Manual Entry</a><a class="active" href="finance_journal.php"><i class="dot"></i>Journal Ledger</a><a href="finance_profit_loss.php"><i class="dot"></i>P&amp;L</a><a href="step16_audit.php"><i class="dot"></i>Audit</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 16C • JOURNAL LEDGER</div><h1>Every finance effect is visible as balanced debit and credit evidence.</h1><p>Reversals remain visible instead of deleting history. Source-linked journals protect against duplicate posting.</p></section><section class="os-card" style="margin-top:14px"><form method="get" class="pp-form"><label>From<input type="date" name="from" value="<?= fj_h($from) ?>"></label><label>To<input type="date" name="to" value="<?= fj_h($to) ?>"></label><label>Search<input name="q" value="<?= fj_h($q) ?>" placeholder="Journal / source / account"></label><button>Apply Filter</button></form></section><?php if($error):?><div class="pp-alert bad"><strong>Journal diagnostic:</strong> <?= fj_h($error) ?></div><?php else:?><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Journal Lines</h2><p><?= fj_h($from) ?> → <?= fj_h($to) ?></p></div><div class="os-status-row"><span class="os-chip">Debit <?= fj_m($tot['debit']) ?></span><span class="os-chip">Credit <?= fj_m($tot['credit']) ?></span><span class="os-chip <?= abs($tot['debit']-$tot['credit'])<0.01?'good':'' ?>">Difference <?= fj_m($tot['debit']-$tot['credit']) ?></span></div></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date / Journal</th><th>Source</th><th>Account</th><th>Debit</th><th>Credit</th><th>Memo</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?= fj_h($r['journal_number']) ?></b><small><?= fj_h($r['journal_date'].' • '.$r['journal_type']) ?></small></td><td><?= fj_h($r['source_code']?:'—') ?><small><?= fj_h(($r['source_type']?:'manual').($r['source_id']?' #'.$r['source_id']:'')) ?></small></td><td><b><?= fj_h($r['account_code'].' • '.$r['account_name']) ?></b><?= $r['cash_account_name']?'<small>Cashbook: '.fj_h($r['cash_account_name']).'</small>':'' ?></td><td><?= (float)$r['debit_amount']>0?fj_m($r['debit_amount']):'—' ?></td><td><?= (float)$r['credit_amount']>0?fj_m($r['credit_amount']):'—' ?></td><td><?= fj_h($r['line_memo']?:$r['memo']?:'—') ?></td><td><span class="pp-badge <?= $r['status']==='reversed'?'warn':'' ?>"><?= fj_h(strtoupper($r['status'])) ?></span><?= $r['reversal_of_id']?'<small>Reversal of #'.(int)$r['reversal_of_id'].'</small>':'' ?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No journal lines in this period.</td></tr><?php endif;?></tbody></table></div></section><div class="os-footer-note"><strong>Balance rule:</strong> every journal is validated before posting; total debit must equal total credit within ₹0.01.</div><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
